def cantor_numbering(N: int) -> str:
    """Return the fraction at position N in the Cantor table."""
    if not isinstance(N, int) or N <= 0:
        raise ValueError("N must be a positive integer")
    # Find the diagonal `d` that contains the N-th term.
    low, high = 1, 1
    while high * (high + 1) // 2 < N:
        high <<= 1
    while low < high:
        mid = (low + high) // 2
        if mid * (mid + 1) // 2 >= N:
            high = mid
        else:
            low = mid + 1
    d = low
    # Number of terms before this diagonal
    prev = (d - 1) * d // 2
    k = N - prev  # position within the diagonal, 1-indexed
    if d % 2 == 0:
        numerator = k
        denominator = d - k + 1
    else:
        numerator = d - k + 1
        denominator = k
    return f"{numerator}/{denominator}"

def max_product(num_str: str, N: int, K: int) -> int:
    """
    Returns the maximum product that can be obtained by inserting K multiplication signs into the number string `num_str`.
    Each partition is interpreted as an integer (leading zeros are ignored by int conversion). If K is invalid (negative or greater than N-1),
    the function returns 0. The function works for non-empty strings of decimal digits.
    """
    # Sanitize input length
    num_str = num_str.strip()
    if not num_str:
        return 0
    N_actual = len(num_str)
    if N != N_actual:
        N = N_actual

    # Validate K
    if K < 0 or K > N - 1:
        return 0
    if K == 0:
        try:
            return int(num_str)
        except ValueError:
            return 0

    # Precompute substring integer values
    val = [[0] * (N + 1) for _ in range(N)]
    for i in range(N):
        for j in range(i + 1, N + 1):
            # Convert substring num_str[i:j] to integer
            try:
                val[i][j] = int(num_str[i:j])
            except ValueError:
                val[i][j] = 0

    # DP table: dp[i][k] = max product using first i characters with k multiplication signs
    dp = [[0] * (K + 1) for _ in range(N + 1)]
    for i in range(1, N + 1):
        dp[i][0] = val[0][i]

    for i in range(1, N + 1):
        max_k_for_i = min(K, i - 1)  # need at least k+1 parts to split i characters
        for k in range(1, max_k_for_i + 1):
            best = 0
            # t is the end position of the previous part
            for t in range(k, i):
                left = dp[t][k - 1]
                current = left * val[t][i]
                if current > best:
                    best = current
            dp[i][k] = best

    return dp[N][K] if K <= N - 1 else 0

def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    """
    Converts a list of polynomial coefficients into a formatted string representation.

    Args:
        n (int): The highest degree of the polynomial.
        coeffs (List[int]): A list of coefficients, starting with the coefficient of the highest degree term.

    Returns:
        str: The string representation of the polynomial.
    """
    if len(coeffs) != n + 1:
        raise ValueError("Length of coeffs must be n + 1")

    parts = []

    for idx, coeff in enumerate(coeffs):
        if coeff == 0:
            continue

        degree = n - idx
        abs_coeff = abs(coeff)

        # Determine sign
        sign = '-' if coeff < 0 else '+'
        is_first = not parts

        # Coefficient string
        if degree == 0:
            coeff_str = str(abs_coeff)
        else:
            coeff_str = '' if abs_coeff == 1 else str(abs_coeff)

        # Variable part
        if degree > 1:
            var_str = f'x^{degree}'
        elif degree == 1:
            var_str = 'x'
        else:
            var_str = ''

        term = coeff_str + var_str

        if is_first:
            if sign == '-':
                parts.append('-' + term)
            else:
                parts.append(term)
        else:
            parts.append(sign + term)

    return ''.join(parts) if parts else '0'

def decode(encoded: str, original: str, message: str) -> str:
    """
    Decodes an encrypted message using a cipher derived from a known encoded-original pair.

    The function builds a mapping from encoded letters to their original letters and uses this
    mapping to decode a given encrypted message. If a contradiction is found during mapping
    construction, or not all letters are represented in the mapping, the function returns "Failed".

    Args:
        encoded (str): A string representing the encoded information.
        original (str): A string representing the original information corresponding to the encoded string.
        message (str): A string representing the encrypted message to be decoded.

    Returns:
        str: The decoded message if successful, or "Failed" if the decoding is not possible.
    """
    if len(encoded) != len(original):
        return "Failed"

    mapping = {}
    revmap = {}
    for e, o in zip(encoded, original):
        if e in mapping:
            if mapping[e] != o:
                return "Failed"
        else:
            if o in revmap and revmap[o] != e:
                return "Failed"
            mapping[e] = o
            revmap[o] = e

    # Check that mapping covers all 26 uppercase letters
    if len(mapping) != 26:
        return "Failed"

    # Decode the message
    decoded = []
    for ch in message:
        if ch not in mapping:
            return "Failed"
        decoded.append(mapping[ch])

    return "".join(decoded)

def generate_numbers(n, rules) -> int:
    """
    Generate all unique numbers from the given number by applying transformation rules
    using breadth-first search (BFS). Each rule allows a single digit to be transformed
    into another. The function returns the count of unique numbers that can be generated
    from the original number, including the number itself.

    Args:
        n (int): The original integer number to transform.
        rules (list of tuples): A list of transformation rules. Each rule is a tuple
                                (x, y) indicating that digit x can be transformed into y.

    Returns:
        int: The total count of unique numbers that can be generated.
    """
    # Input validation
    if not isinstance(n, int):
        raise TypeError("n must be an integer")
    if not isinstance(rules, list):
        raise TypeError("rules must be a list of tuples")
    for rule in rules:
        if not (isinstance(rule, tuple) and len(rule) == 2):
            raise ValueError("each rule must be a tuple of length 2")
        if not (isinstance(rule[0], int) and isinstance(rule[1], int)):
            raise TypeError("rule elements must be integers")

    # Build a mapping from source digit to a set of target digits
    transform_map = {}
    for src, tgt in rules:
        transform_map.setdefault(src, set()).add(tgt)

    # BFS initialization
    seen = {n}
    queue = [n]

    while queue:
        current = queue.pop(0)
        current_str = str(current)
        for idx, ch in enumerate(current_str):
            digit = int(ch)
            if digit in transform_map:
                for new_digit in transform_map[digit]:
                    new_str = current_str[:idx] + str(new_digit) + current_str[idx+1:]
                    new_num = int(new_str)
                    if new_num not in seen:
                        seen.add(new_num)
                        queue.append(new_num)
    return len(seen)

def check_scenario(scenario: str, liar_count: set, statements: dict, days_of_week: set) -> bool:
    """
    Evaluates the consistency of a scenario where one participant is the criminal based on the
    given statements. `liar_count` contains the names of participants who are assumed to be liars.
    Statements that mention any day of the week (from `days_of_week`) are ignored.

    Parameters:
    - scenario (str): Potential criminal name.
    - liar_count (set): Names of liars.
    - statements (dict): Mapping from participant names to a list of their statements.
    - days_of_week (set): Set of day names (e.g., {"MONDAY", "TUESDAY"}).

    Returns:
    - bool: True if the scenario is consistent with all relevant statements, False otherwise.
    """
    import re

    # Pre‑process for case‑insensitivity
    scenario_u = scenario.upper()
    liar_set = {name.upper() for name in liar_count}
    days = {day.upper() for day in days_of_week}

    # Helper to determine if a statement is about the day of week
    def is_day_statement(stmt: str) -> bool:
        words = set(re.findall(r"\b\w+\b", stmt.upper()))
        return not days.isdisjoint(words)

    # Helper to assess truth of a single statement
    def eval_truth(stmt: str, speaker: str) -> bool | None:
        stmt = stmt.strip().rstrip(".")
        # Skip if not relevant
        # Patterns
        patterns = [
            (r"^I\s+am\s+guilty$", lambda _: speaker == scenario_u),
            (r"^I\s+am\s+not\s+guilty$", lambda _: speaker != scenario_u),
            (r"^(\w+)\s+is\s+guilty$", lambda t: t == scenario_u),
            (r"^(\w+)\s+is\s+not\s+guilty$", lambda t: t != scenario_u),
        ]
        for pat, func in patterns:
            match = re.match(pat, stmt, re.IGNORECASE)
            if match:
                if match.lastindex is None:  # no capture group
                    return func(None)
                return func(match.group(1).upper())
        return None  # Cannot parse

    # Iterate over each speaker and their statements
    for speaker_raw, stmts in statements.items():
        speaker = speaker_raw.upper()
        is_liar = speaker in liar_set
        for stmt in stmts:
            if is_day_statement(stmt):
                continue  # Skip day‑related statements
            truth = eval_truth(stmt, speaker)
            if truth is None:
                continue  # Unparseable statements are ignored
            # liars must utter false statements, truthers must utter true statements
            if is_liar and truth:
                return False
            if not is_liar and not truth:
                return False
    return True

def minimum_students_to_leave(heights):
    """
    Return the minimum number of students that need to leave so that the remaining heights
    form a strictly increasing then strictly decreasing sequence (mountain shape).
    This is equivalent to removing the fewest elements to obtain the longest
    bitonic subsequence.

    :param heights: List[int] – list of student heights.
    :return: int – minimum number of students to remove.
    """
    if not isinstance(heights, list):
        raise TypeError("heights must be a list")
    for h in heights:
        if not isinstance(h, int):
            raise TypeError("all elements of heights must be integers")

    n = len(heights)
    if n <= 1:
        return 0

    # LIS[i]: longest increasing subsequence ending at index i
    lis = [1] * n
    for i in range(n):
        for j in range(i):
            if heights[j] < heights[i] and lis[j] + 1 > lis[i]:
                lis[i] = lis[j] + 1

    # LDS[i]: longest decreasing subsequence starting at index i
    lds = [1] * n
    for i in reversed(range(n)):
        for j in range(i + 1, n):
            if heights[i] > heights[j] and lds[j] + 1 > lds[i]:
                lds[i] = lds[j] + 1

    # Longest bitonic subsequence length
    best = 0
    for i in range(n):
        # subtract 1 to avoid counting peak twice
        bitonic_len = lis[i] + lds[i] - 1
        if bitonic_len > best:
            best = bitonic_len

    return n - best

def sort_students(student_scores):
    """
    Sorts a list of students based on their scores. The students are sorted primarily by their total score (descending),
    then by their Chinese score (descending), and finally by their student number (ascending) in case of a tie.

    Args:
    student_scores (list): A list of tuples, where each tuple consists of (student_number, total_score, Chinese_score).

    Returns:
    list: A list of tuples sorted according to the above rules.
    """
    try:
        # Validate that input is a list of tuples with three elements each
        if not isinstance(student_scores, list):
            raise TypeError("student_scores must be a list")
        for item in student_scores:
            if not (isinstance(item, tuple) and len(item) == 3):
                raise TypeError("Each item in student_scores must be a tuple of (student_number, total_score, Chinese_score)")
            if not (isinstance(item[0], int) and isinstance(item[1], (int, float)) and isinstance(item[2], (int, float))):
                raise TypeError("student_number must be int; total_score and Chinese_score must be numeric")
        # Sort using the specified criteria
        return sorted(student_scores, key=lambda t: (-t[1], -t[2], t[0]))
    except Exception as e:
        raise ValueError(f"Invalid input encountered: {e}") from e
